// AI Refactor: Decoupled Logic & Extracted Components
import { useDashboardData } from '../hooks/useDashboardData';
import { AdminPanel, MetricCharts } from './widgets';

export default function Dashboard() {
  // State and fetching extracted to a custom hook
  const { data, loading, userRole } = useDashboardData();

  if (loading) return <LoadingSpinner />;

  return (
    <DashboardGrid>
      {userRole === 'admin' && <AdminPanel data={data.adminMetrics} />}
      <MetricCharts data={data.metrics} />
    </DashboardGrid>
  );
}
